// Breaking-change check: compares the API description in the working tree (docs/openapi.json, regenerated by
// `npm run check:openapi`/export) with the one committed at a git ref (default: the last release tag, else HEAD~20).
//   node scripts/check-api-compat.mjs [gitRef]
// Reported as breaking, because an existing client would stop working:
//   - a path or method that disappeared
//   - a response property (success responses) that disappeared or changed type
//   - a request property that became required, or a new required request property
// Additions (new paths, new optional properties, new response properties) are fine and never reported.
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const ref = process.argv[2] ?? 'HEAD';
const now = JSON.parse(readFileSync('docs/openapi.json', 'utf8'));
let before;
try { before = JSON.parse(execFileSync('git', ['show', `${ref}:docs/openapi.json`], { encoding: 'utf8', maxBuffer: 50e6 })); }
catch { console.log(`No docs/openapi.json at ${ref}: nothing to compare with.`); process.exit(0); }

const problems = [];
const METHODS = ['get', 'post', 'put', 'patch', 'delete'];
const resolve = (spec, s) => (s && s.$ref ? spec.components?.schemas?.[s.$ref.split('/').pop()] ?? {} : s ?? {});

function compareResponse(where, a, b, depth = 0) {
  a = resolve(before, a); b = resolve(now, b);
  if (depth > 8 || !a.type) return;
  if (b.type && a.type !== b.type) { problems.push(`${where}: type changed from ${a.type} to ${b.type}`); return; }
  if (a.type === 'object') {
    for (const [name, sub] of Object.entries(a.properties ?? {})) {
      if (!(name in (b.properties ?? {}))) problems.push(`${where}: response property "${name}" was removed`);
      else compareResponse(`${where}.${name}`, sub, b.properties[name], depth + 1);
    }
  } else if (a.type === 'array' && a.items && b.items) compareResponse(`${where}[]`, a.items, b.items, depth + 1);
}

function compareRequest(where, a, b) {
  a = resolve(before, a); b = resolve(now, b);
  const wasRequired = new Set(a.required ?? []);
  for (const name of b.required ?? []) if (!wasRequired.has(name)) problems.push(`${where}: request property "${name}" is now required`);
}

for (const [path, ops] of Object.entries(before.paths ?? {})) {
  for (const method of METHODS) {
    if (!ops[method]) continue;
    const label = `${method.toUpperCase()} ${path}`;
    const op = now.paths?.[path]?.[method];
    if (!op) { problems.push(`${label}: no longer exists`); continue; }
    const old200 = ops[method].responses?.['200']?.content?.['application/json']?.schema;
    const new200 = op.responses?.['200']?.content?.['application/json']?.schema;
    if (old200 && new200) compareResponse(`${label} 200`, old200, new200);
    const oldBody = ops[method].requestBody?.content?.['application/json']?.schema;
    const newBody = op.requestBody?.content?.['application/json']?.schema;
    if (oldBody && newBody) compareRequest(`${label} body`, oldBody, newBody);
  }
}

console.log(`Compared ${Object.keys(before.paths ?? {}).length} paths at ${ref} with the working tree.`);
if (problems.length) { console.log(problems.map((p) => `  BREAKING ${p}`).join('\n')); process.exit(1); }
console.log('No breaking changes.');
